assert.deepEqual(unifiedHunks(['a', 'g1', 'g2', 'g3', 'b'], ['A', 'g1', 'g2', 'g3', 'B'], { context: 1 }), [
  { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: ['-a', '+A', ' g1'] },
  { oldStart: 4, oldLines: 2, newStart: 4, newLines: 2, lines: [' g3', '-b', '+B'] },
]);
const base = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
const invalid = [null, {}, { ...base, oldStart: 0 }, { ...base, oldStart: -1 },
  { ...base, oldStart: 2.5 }, { ...base, oldLines: -1 }, { ...base, newLines: NaN },
  { ...base, oldStart: 5 }, { ...base, oldLines: 3 }, { ...base, newStart: 1 },
  { ...base, newLines: 2 }, { ...base, oldLines: 0 }, { ...base, lines: ['-wrong', '+B'] },
  { ...base, lines: [' wrong'] }, { ...base, lines: ['?b'] }, { ...base, lines: [''] },
  { ...base, lines: [5] }, { ...base, lines: null }];
for (const h of invalid) assert.throws(() => applyHunks(['a', 'b', 'c'], [h]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(['a', 'b', 'c'], [base, base]), /hunk 1 does not apply/);
const overlapping = { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: [' a', ' b'] };
assert.throws(() => applyHunks(['a', 'b', 'c'], [overlapping, base]), /hunk 1 does not apply/);
assert.deepEqual(applyHunks(['a'], [
  { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] },
  { oldStart: 0, oldLines: 0, newStart: 2, newLines: 1, lines: ['+y'] },
