  assert.deepEqual(patched, b);
  assert.equal(script.filter(e => e.op !== 'equal').length, 4);
  assert.ok(elapsed < 1000, `20000-line pipeline took ${elapsed} ms`);
  timings.push(`${repetitive ? 'repeated' : 'unique'}=${elapsed.toFixed(2)}ms`);
