const many = Array.from({ length: 20000 }, () => '');
assert.deepEqual(applyHunks([], unifiedHunks([], many)), many);
assert.deepEqual(applyHunks(many, unifiedHunks(many, [])), []);
console.log(`Passed ${pairs} exhaustive pairs, 1000 seeded pairs, hunk boundaries/validation, and 20000-line roundtrips; ${timings.join(', ')}`);
